    questions: [
      { id: "carl-704", no: 704, priority: "P1", difficulty: "Easy", category: "array", title: "二分查找", key: "维护有序数组中的闭区间 [left, right]；循环条件、边界更新和返回值必须使用同一套区间定义。", answer: ["先确认数组有序、目标和重复元素语义", "使用 left <= right，mid 命中直接返回", "nums[mid] 小则 left=mid+1，否则 right=mid-1"], python: "left, right = 0, len(nums) - 1\nwhile left <= right:\n    mid = (left + right) // 2", complexity: "时间 O(log n)，空间 O(1)。", acceptance: "覆盖空数组、首尾命中、未命中和重复值；能解释 bisect_left 的返回语义。", pitfall: "把闭区间循环条件写成 left < right，却仍用 right=mid-1，造成漏检。", link: "https://leetcode.com/problems/binary-search/" },
      { id: "carl-27", no: 27, priority: "P1", difficulty: "Easy", category: "array", title: "移除元素", key: "快指针扫描所有输入，慢指针只指向下一个保留位置；原地覆盖并返回新长度。", answer: ["fast 负责读，slow 负责写", "当 nums[fast] != val 时写入 nums[slow]", "只保证前 slow 个元素有效，不要求清理尾部"], python: "slow = 0\nfor value in nums:\n    if value != val:\n        nums[slow] = value; slow += 1", complexity: "时间 O(n)，空间 O(1)。", acceptance: "覆盖全部删除、无删除、空数组；说明 Python 切片删除为什么不是 O(1) 额外空间语义。", pitfall: "遍历时 remove 或 pop 导致跳过元素并退化到 O(n²)。", link: "https://leetcode.com/problems/remove-element/" },
      { id: "carl-209", no: 209, priority: "P0", difficulty: "Medium", category: "array", title: "长度最小的子数组", key: "正整数数组使窗口和具有单调性：右边扩张达到阈值后，左边持续收缩并更新最短长度。", answer: ["right 每次加入一个元素", "window_sum >= target 时循环移动 left", "用 inf 表示尚未找到，最后转换为 0"], python: "left = total = 0\nfor right, value in enumerate(nums):\n    total += value\n    while total >= target: ...", complexity: "时间 O(n)，空间 O(1)。", acceptance: "覆盖无解、单元素命中、整个数组；能说明存在负数时为什么滑窗失效。", pitfall: "满足条件只收缩一次，错过更短窗口；或对含负数输入照搬本算法。", link: "https://leetcode.com/problems/minimum-size-subarray-sum/" },
      { id: "carl-215", no: 215, priority: "P0", difficulty: "Medium", category: "array", title: "数组中的第 K 个最大元素", key: "面试先给大小为 k 的小顶堆 O(n log k)，再比较 quickselect 的平均 O(n) 与最坏 O(n²)。", answer: ["遍历元素并压入 min-heap", "堆大小超过 k 时弹出最小值", "结束时 heap[0] 是第 k 大"], python: "heap = []\nfor x in nums:\n    heapq.heappush(heap, x)\n    if len(heap) > k: heapq.heappop(heap)", complexity: "小顶堆 O(n log k)/O(k)；quickselect 平均 O(n)。", acceptance: "覆盖 k=1、k=n、重复值；能解释流式数据为什么选择 heap。", pitfall: "Python heapq 是小顶堆；不要无必要把所有元素取负或全量排序。", link: "https://leetcode.com/problems/kth-largest-element-in-an-array/" },
      { id: "carl-206", no: 206, priority: "P0", difficulty: "Easy", category: "linked", title: "反转链表", key: "遍历时先保存 next，再把 current.next 指向 prev；三个指针完成原地反转。", answer: ["prev=None，cur=head", "保存 nxt=cur.next 后再改指针", "整体移动 prev/cur，最后返回 prev"], python: "prev, cur = None, head\nwhile cur:\n    nxt = cur.next\n    cur.next = prev\n    prev, cur = cur, nxt", complexity: "时间 O(n)，空间 O(1)。", acceptance: "覆盖空链表、单节点和两节点；逐步画出指针状态。", pitfall: "先改 cur.next 却没有保存 nxt，导致剩余链表丢失。", link: "https://leetcode.com/problems/reverse-linked-list/" },
      { id: "carl-19", no: 19, priority: "P1", difficulty: "Medium", category: "linked", title: "删除链表的倒数第 N 个节点", key: "使用 dummy 统一删除头节点；fast 先走 n+1 步，与 slow 同速移动，slow 最终停在待删节点前驱。", answer: ["dummy.next=head，fast/slow 从 dummy 出发", "fast 前进 n+1 次形成固定间距", "一起移动到 fast 为空，修改 slow.next"], python: "dummy = ListNode(0, head)\nfast = slow = dummy\nfor _ in range(n + 1): fast = fast.next", complexity: "时间 O(n)，空间 O(1)。", acceptance: "覆盖删除头、尾和单节点；确认 n 合法的题目约束。", pitfall: "fast 只先走 n 步导致 slow 停在待删节点而非前驱。", link: "https://leetcode.com/problems/remove-nth-node-from-end-of-list/" },
      { id: "carl-142", no: 142, priority: "P0", difficulty: "Medium", category: "linked", title: "环形链表 II", key: "Floyd 快慢指针先判断相遇；相遇后一个指针回到 head，两者同速再相遇即为环入口。", answer: ["slow 走 1、fast 走 2，若 fast 到空则无环", "首次相遇后 reset 一个指针到 head", "两指针每次走 1，下一次相遇返回入口"], python: "slow = fast = head\nwhile fast and fast.next:\n    slow, fast = slow.next, fast.next.next", complexity: "时间 O(n)，空间 O(1)。", acceptance: "能推导 head→入口距离等于相遇点→入口的等价关系；覆盖自环。", pitfall: "用 visited set 虽正确但空间 O(n)，或相遇后继续让 fast 走两步。", link: "https://leetcode.com/problems/linked-list-cycle-ii/" },
      { id: "carl-146", no: 146, priority: "P0", difficulty: "Medium", category: "linked", title: "LRU Cache", key: "哈希表负责 O(1) 定位，双向链表维护最近使用顺序；访问和更新都把节点移到 MRU 端。", answer: ["dummy head/tail 避免边界分支", "get 命中后 detach 再 append 到尾部", "put 超容量时弹出头部 LRU 并同步删除 dict"], python: "cache = {}  # key -> node\n# _remove(node) + _append(node)\n# get/put 均复用两个原子操作", complexity: "get/put 平均 O(1)，空间 O(capacity)。", acceptance: "覆盖 capacity=1、更新已有 key、连续淘汰；能讨论并发锁粒度。", pitfall: "只用 OrderedDict 却解释不出核心结构，或链表删除后忘记同步哈希表。", link: "https://leetcode.com/problems/lru-cache/" },
      { id: "carl-242", no: 242, priority: "P1", difficulty: "Easy", category: "hash", title: "有效的字母异位词", key: "比较字符频次；字符集固定时用数组，通用 Unicode 输入用 Counter/dict。", answer: ["长度不同可提前返回", "统计 s 增量、t 减量，或直接比较 Counter", "说明空间复杂度取决于字符集大小"], python: "return Counter(s) == Counter(t)", complexity: "时间 O(n)，空间 O(k)。", acceptance: "覆盖空串、重复字符和 Unicode；能给出不用 Counter 的固定 26 位数组。", pitfall: "排序方案是 O(n log n)；不要把固定字符集 O(1) 与通用字典 O(k) 混为一谈。", link: "https://leetcode.com/problems/valid-anagram/" },
      { id: "carl-1", no: 1, priority: "P0", difficulty: "Easy", category: "hash", title: "两数之和", key: "单次遍历时查找 complement 是否已经出现，再记录当前值；保证不会重复使用同一元素。", answer: ["对 x 计算 need=target-x", "need 在 seen 时返回两个下标", "否则 seen[x]=index"], python: "seen = {}\nfor i, x in enumerate(nums):\n    if target - x in seen: return [seen[target - x], i]\n    seen[x] = i", complexity: "平均时间 O(n)，空间 O(n)。", acceptance: "覆盖重复元素 [3,3]、负数和唯一解；说明先查后存的原因。", pitfall: "先存当前元素可能在 target=2*x 时错误复用自己。", link: "https://leetcode.com/problems/two-sum/" },
      { id: "carl-15", no: 15, priority: "P1", difficulty: "Medium", category: "hash", title: "三数之和", key: "排序后枚举第一个数，再用左右指针寻找补数；在三个层次正确去重。", answer: ["排序，nums[i]>0 时提前结束", "跳过重复 i，left/right 根据和移动", "命中后同时跳过重复 left/right 值"], python: "nums.sort()\nfor i in range(len(nums) - 2):\n    left, right = i + 1, len(nums) - 1", complexity: "时间 O(n²)，额外空间取决于排序实现。", acceptance: "覆盖全零、重复答案和无解；输出不能含重复三元组。", pitfall: "在移动前去重或直接用 set 收集所有结果，掩盖去重逻辑与额外空间。", link: "https://leetcode.com/problems/3sum/" },
      { id: "carl-3", no: 3, priority: "P0", difficulty: "Medium", category: "hash", title: "无重复字符的最长子串", key: "维护字符最后出现位置；左边界只能单调右移到 max(left, last[ch]+1)。", answer: ["right 扫描字符并读取最后位置", "重复字符仍在窗口内时推进 left", "更新 last[ch] 和最大窗口长度"], python: "left = best = 0\nlast = {}\nfor right, ch in enumerate(s):\n    left = max(left, last.get(ch, -1) + 1)", complexity: "时间 O(n)，空间 O(k)。", acceptance: "覆盖 abba、全重复、空串；明确 Python 字符是 Unicode code point。", pitfall: "直接令 left=last[ch]+1 会在 abba 中让左边界后退。", link: "https://leetcode.com/problems/longest-substring-without-repeating-characters/" },
      { id: "carl-20", no: 20, priority: "P0", difficulty: "Easy", category: "stack", title: "有效的括号", key: "遇到左括号压入期望的右括号；遇到右括号时必须与栈顶匹配，结束时栈为空。", answer: ["用映射把 opener 转为期望 closer", "右括号出现时检查空栈和栈顶", "扫描结束返回 not stack"], python: "pairs = {'(': ')', '[': ']', '{': '}'}\nstack = []", complexity: "时间 O(n)，空间 O(n)。", acceptance: "覆盖空串、奇数长度、错误嵌套和提前右括号。", pitfall: "只比较左右括号数量，无法发现 ([)] 这类错误嵌套。", link: "https://leetcode.com/problems/valid-parentheses/" },
      { id: "carl-239", no: 239, priority: "P0", difficulty: "Hard", category: "stack", title: "滑动窗口最大值", key: "单调递减 deque 存下标：队首是当前最大值；过期下标从左弹出，新值支配的下标从右弹出。", answer: ["先移除 index <= i-k 的过期元素", "while nums[dq[-1]] <= nums[i] 从右弹出", "追加 i，窗口形成后记录 nums[dq[0]]"], python: "dq = deque()\nfor i, x in enumerate(nums):\n    while dq and dq[0] <= i - k: dq.popleft()", complexity: "时间 O(n)，空间 O(k)。", acceptance: "覆盖 k=1、k=n、递增/递减和重复值；解释每个下标最多进出一次。", pitfall: "deque 中存值而非下标，无法可靠判断元素是否过期。", link: "https://leetcode.com/problems/sliding-window-maximum/" },
      { id: "carl-347", no: 347, priority: "P1", difficulty: "Medium", category: "stack", title: "前 K 个高频元素", key: "Counter 统计频次；用大小 k 的小顶堆保留最高频，或用 bucket 在 O(n) 时间取结果。", answer: ["freq=Counter(nums)", "遍历 (count,value) 并维护 k 大小 heap", "弹出结果；题目通常不要求顺序"], python: "freq = Counter(nums)\nheap = []\nfor value, count in freq.items():\n    heapq.heappush(heap, (count, value))", complexity: "堆 O(n log k)/O(n)；桶 O(n)/O(n)。", acceptance: "覆盖 k=唯一元素数、频率相同和负数；能比较 heap 与 bucket。", pitfall: "heap tuple 的第一项必须是频次；误用负频率会改变保留逻辑。", link: "https://leetcode.com/problems/top-k-frequent-elements/" },
      { id: "carl-102", no: 102, priority: "P0", difficulty: "Medium", category: "tree", title: "二叉树的层序遍历", key: "BFS 使用 deque；每轮先固定当前队列长度，只处理这一层并收集下一层节点。", answer: ["空树返回 []，根节点入队", "level_size=len(queue) 固定本层边界", "popleft 节点、追加孩子并保存 level"], python: "queue = deque([root])\nwhile queue:\n    level = []\n    for _ in range(len(queue)): ...", complexity: "时间 O(n)，空间 O(w)，w 为最大层宽。", acceptance: "覆盖空树、单节点和不平衡树；说明为什么不能在 for 中动态读取 len(queue)。", pitfall: "使用 list.pop(0) 导致每次 O(n) 移动，应使用 deque.popleft()。", link: "https://leetcode.com/problems/binary-tree-level-order-traversal/" },
      { id: "carl-104", no: 104, priority: "P1", difficulty: "Easy", category: "tree", title: "二叉树的最大深度", key: "递归定义为 1+max(left_depth,right_depth)；也可用层序 BFS 的层数回答。", answer: ["明确空节点深度为 0", "后序递归先得到左右子树深度", "返回 1+较大值，并说明递归栈"], python: "def maxDepth(node):\n    if not node: return 0\n    return 1 + max(maxDepth(node.left), maxDepth(node.right))", complexity: "时间 O(n)，递归空间 O(h)。", acceptance: "覆盖空树、链状树；能说明极深树在 Python 中的递归深度风险。", pitfall: "把高度和节点数/边数定义混用；LeetCode 此题以节点数计深度。", link: "https://leetcode.com/problems/maximum-depth-of-binary-tree/" },
      { id: "carl-98", no: 98, priority: "P0", difficulty: "Medium", category: "tree", title: "验证二叉搜索树", key: "每个节点必须满足整个祖先传下来的 (low, high) 范围，而不只是与直接孩子比较。", answer: ["递归携带严格上下界", "node.val <= low 或 >= high 立即失败", "左子树上界=node.val，右子树下界=node.val"], python: "def valid(node, low=float('-inf'), high=float('inf')):\n    if not node: return True", complexity: "时间 O(n)，空间 O(h)。", acceptance: "覆盖重复值和 [5,1,4,3,6]；也能给出中序严格递增方案。", pitfall: "只检查 left.val < root.val < right.val，忽略跨层违反祖先边界。", link: "https://leetcode.com/problems/validate-binary-search-tree/" },
      { id: "carl-236", no: 236, priority: "P0", difficulty: "Medium", category: "tree", title: "二叉树的最近公共祖先", key: "后序递归：当前节点等于 p/q 就返回；左右均非空说明 p、q 分居两侧，当前节点即 LCA。", answer: ["空节点或命中 p/q 时返回当前节点", "递归获得 left 与 right", "两边都有值返回 root，否则返回非空一边"], python: "if not root or root is p or root is q: return root\nleft = lca(root.left, p, q)\nright = lca(root.right, p, q)", complexity: "时间 O(n)，空间 O(h)。", acceptance: "覆盖一个节点是另一个祖先、p=q 的约束讨论；说明题目保证节点存在。", pitfall: "用节点值比较而不是节点身份，在值可能重复的树中不可靠。", link: "https://leetcode.com/problems/lowest-common-ancestor-of-a-binary-tree/" },
      { id: "carl-77", no: 77, priority: "P1", difficulty: "Medium", category: "backtrack", title: "组合", key: "路径表示已选择元素，start 控制下一次选择范围；递归前选择、递归后撤销。", answer: ["len(path)==k 时复制结果", "从 start 遍历候选并 append", "递归 i+1 后 pop；用剩余数量剪枝"], python: "def dfs(start):\n    if len(path) == k:\n        ans.append(path.copy()); return", complexity: "输出规模主导，约 O(C(n,k)·k)，递归空间 O(k)。", acceptance: "覆盖 k=0/k=n；写出 upper=n-(k-len(path))+1 的剪枝边界。", pitfall: "ans.append(path) 保存同一可变列表引用，最终结果会被回溯修改。", link: "https://leetcode.com/problems/combinations/" },
      { id: "carl-46", no: 46, priority: "P0", difficulty: "Medium", category: "backtrack", title: "全排列", key: "每层选择一个尚未使用的元素；used 按索引记录状态，路径长度等于 n 时复制答案。", answer: ["path 与 used 初始化", "遍历所有 index，跳过已使用", "标记→递归→取消标记"], python: "used = [False] * len(nums)\ndef dfs():\n    if len(path) == len(nums): ans.append(path.copy())", complexity: "时间 O(n·n!)，空间 O(n)。", acceptance: "覆盖单元素；能扩展到含重复元素的排序+同层去重。", pitfall: "用 value in path 判断会增加 O(n) 且无法正确处理重复值版本。", link: "https://leetcode.com/problems/permutations/" },
      { id: "carl-56", no: 56, priority: "P1", difficulty: "Medium", category: "greedy", title: "合并区间", key: "按起点排序；当前区间与结果末尾重叠时扩展 end，否则开启新区间。", answer: ["intervals 按 start 升序", "start <= merged[-1][1] 时更新最大 end", "否则追加当前区间副本"], python: "intervals.sort(key=lambda x: x[0])\nmerged = []", complexity: "时间 O(n log n)，空间取决于输出与排序。", acceptance: "覆盖相邻端点、完全包含、空输入；说明是否允许修改输入。", pitfall: "只比较相邻原区间而不是当前已合并区间的最大 end。", link: "https://leetcode.com/problems/merge-intervals/" },
      { id: "carl-55", no: 55, priority: "P1", difficulty: "Medium", category: "greedy", title: "跳跃游戏", key: "维护当前能到达的最远下标；若扫描位置超过 farthest 则失败，否则用 i+nums[i] 扩展覆盖范围。", answer: ["farthest=0，从左向右扫描", "i > farthest 说明出现不可达断点", "更新 farthest，达到末尾可提前返回"], python: "farthest = 0\nfor i, step in enumerate(nums):\n    if i > farthest: return False\n    farthest = max(farthest, i + step)", complexity: "时间 O(n)，空间 O(1)。", acceptance: "覆盖 [0]、[3,2,1,0,4] 和提前到达；解释贪心不需要关心具体路径。", pitfall: "在某个 nums[i]==0 时立即失败；零点可能已被之前的覆盖范围跨过。", link: "https://leetcode.com/problems/jump-game/" },
      { id: "carl-53", no: 53, priority: "P0", difficulty: "Medium", category: "dp", title: "最大子数组和", key: "Kadane：以当前位置结尾的最优和要么单独从 nums[i] 开始，要么接在此前最优后；同时维护全局最大值。", answer: ["current=best=nums[0]", "current=max(x,current+x)", "best=max(best,current)"], python: "current = best = nums[0]\nfor x in nums[1:]:\n    current = max(x, current + x)\n    best = max(best, current)", complexity: "时间 O(n)，空间 O(1)。", acceptance: "覆盖全负数、单元素；能扩展保存最优区间左右边界。", pitfall: "把初值设为 0 会让全负数组错误返回 0。", link: "https://leetcode.com/problems/maximum-subarray/" },
      { id: "carl-70", no: 70, priority: "P1", difficulty: "Easy", category: "dp", title: "爬楼梯", key: "到第 i 阶的方案来自 i−1 和 i−2；滚动变量把 DP 空间从 O(n) 降到 O(1)。", answer: ["定义 dp[i] 为到达 i 的方案数", "转移 dp[i]=dp[i-1]+dp[i-2]", "确认 n=1/2 初值后滚动更新"], python: "a, b = 1, 2\nfor _ in range(3, n + 1):\n    a, b = b, a + b", complexity: "时间 O(n)，空间 O(1)。", acceptance: "覆盖 n=1、n=2；能说明它与 Fibonacci 的索引关系。", pitfall: "没有先处理 n<=2，导致 b 对 n=1 返回错误。", link: "https://leetcode.com/problems/climbing-stairs/" },
      { id: "carl-300", no: 300, priority: "P0", difficulty: "Medium", category: "dp", title: "最长递增子序列", key: "基础 DP 是 O(n²)；进阶用 tails 维护各长度递增子序列的最小结尾，并用 bisect_left 达到 O(n log n)。", answer: ["对每个 x 找 tails 中第一个 >=x 的位置", "存在则替换以降低该长度的结尾", "否则 append，最终 len(tails) 是 LIS 长度"], python: "tails = []\nfor x in nums:\n    i = bisect_left(tails, x)\n    if i == len(tails): tails.append(x)\n    else: tails[i] = x", complexity: "时间 O(n log n)，空间 O(n)。", acceptance: "覆盖重复值与递减数组；能解释 tails 本身不一定是原数组中的最终 LIS。", pitfall: "严格递增必须用 bisect_left；bisect_right 会把相等值算进长度。", link: "https://leetcode.com/problems/longest-increasing-subsequence/" },
      { id: "carl-322", no: 322, priority: "P0", difficulty: "Medium", category: "dp", title: "零钱兑换", key: "完全背包：dp[a] 表示组成金额 a 的最少硬币数；对每枚硬币正序更新金额。", answer: ["dp=[inf]*(amount+1)，dp[0]=0", "for coin in coins，for a from coin to amount", "dp[a]=min(dp[a],dp[a-coin]+1)，inf 转 -1"], python: "dp = [float('inf')] * (amount + 1)\ndp[0] = 0\nfor coin in coins:\n    for a in range(coin, amount + 1): ...", complexity: "时间 O(amount·len(coins))，空间 O(amount)。", acceptance: "覆盖 amount=0、无解和硬币大于金额；解释完全背包为何正序。", pitfall: "把 dp 初始化为 0 无法区分不可达；或错误使用 0/1 背包的逆序循环。", link: "https://leetcode.com/problems/coin-change/" },
      { id: "carl-1143", no: 1143, priority: "P1", difficulty: "Medium", category: "dp", title: "最长公共子序列", key: "dp[i][j] 表示两个前缀的 LCS 长度；字符相同取左上+1，否则取上方与左方最大值。", answer: ["构造 (m+1)×(n+1) 的零边界", "相同：dp[i][j]=dp[i-1][j-1]+1", "不同：max(dp[i-1][j],dp[i][j-1])"], python: "dp = [[0] * (n + 1) for _ in range(m + 1)]", complexity: "时间 O(mn)，空间 O(mn)，仅长度可压缩到 O(n)。", acceptance: "覆盖空串、完全相同和无公共字符；区分子序列与子串。", pitfall: "二维数组用 [[0]*(n+1)]*(m+1) 会产生行别名，修改一行影响所有行。", link: "https://leetcode.com/problems/longest-common-subsequence/" },
      { id: "carl-200", no: 200, priority: "P0", difficulty: "Medium", category: "graph", title: "岛屿数量", key: "遍历网格，每遇到未访问陆地就增加计数，并用 DFS/BFS 淹没整个连通分量。", answer: ["双重循环扫描每个 cell", "遇到 '1' 后 count+=1 并启动 flood fill", "访问邻居前检查边界与陆地，并标记为 '0' 或 visited"], python: "for r in range(rows):\n    for c in range(cols):\n        if grid[r][c] == '1':\n            islands += 1; flood(r, c)", complexity: "时间 O(mn)，空间最坏 O(mn)。", acceptance: "覆盖空网格、全水、对角不连通；递归 DFS 需说明 Python 栈深风险。", pitfall: "入队后才延迟标记 visited，可能把同一节点重复加入队列。", link: "https://leetcode.com/problems/number-of-islands/" },
      { id: "carl-207", no: 207, priority: "P0", difficulty: "Medium", category: "graph", title: "课程表", key: "把先修关系建成有向图；Kahn 拓扑排序不断取入度为 0 的节点，最终处理数等于课程数则无环。", answer: ["构建 adjacency list 与 indegree", "所有入度 0 节点进入 deque", "弹出课程、降低邻居入度，新为 0 时入队；比较 processed"], python: "graph = defaultdict(list)\nindegree = [0] * numCourses\nqueue = deque(i for i, d in enumerate(indegree) if d == 0)", complexity: "时间 O(V+E)，空间 O(V+E)。", acceptance: "覆盖无依赖、自环、重复边的输入约束；能给出 DFS 三色检测替代方案。", pitfall: "把 prerequisite 边方向建反虽可能仍能判断环，但无法正确解释拓扑顺序语义。", link: "https://leetcode.com/problems/course-schedule/" }
    ]
